21. import com.github.copilot.rpc.PingResponse;
22. import com.github.copilot.rpc.RuntimeConnection;
23. 
24. /**
25.  * Failsafe integration test for the in-process (FFI) transport.
26.  *
27.  * <p>
28.  * Loads the real {@code runtime.node} native library into this test process via
29.  * {@link com.github.copilot.ffi.FfiRuntimeHost}, performs a purely local
30.  * {@code ping} round-trip through the runtime, and stops cleanly. {@code ping}
31.  * is answered by the runtime itself, so no auth or replay proxy is involved —
32.  * this mirrors {@code nodejs/test/e2e/inprocess_ffi.e2e.test.ts},
33.  * {@code go/internal/e2e/inprocess_ffi_e2e_test.go}, and
34.  * {@code python/e2e/test_inprocess_ffi_e2e.py}.
35.  *
36.  * <p>
37.  * {@link InProcessEnvGuard} demonstrates how the harness redirects the native
38.  * runtime's HTTP traffic to the replay proxy (via {@code COPILOT_API_URL}) for
39.  * tests that need session/message round trips over the in-process transport:
40.  * the native library reads environment variables from the live OS process
41.  * environment block, not from the JVM's {@code System.getenv()} snapshot, so
42.  * only a JNA-backed native call can make it visible to code already loaded
43.  * in-process.
44.  *
45.  * <p>
46.  * Run with {@code mvn verify -Pinprocess} from {@code java/sdk}, which sets
47.  * {@code COPILOT_CLI_PATH} to the pinned CLI whose sibling {@code runtime.node}
48.  * this test loads, and forces {@code forkCount=1} because the FFI host and env
49.  * guard mutate process-global state.
50.  *
51.  * <p>
52.  * {@link RequireInProcess} disables this test unless the {@code -Pinprocess}
53.  * profile is active: without it, the {@code copilot-sdk-java-runtime}
54.  * classifier JAR providing {@code runtime.node} is not on the classpath, so the
55.  * test would fail with a {@code FileNotFoundException} rather than being
56.  * skipped.
57.  */
58. @AllowCopilotExperimental
59. @RequireInProcess
60. class InProcessTransportIT {
61. 
62.     private static E2ETestContext ctx;
63. 
64.     @BeforeAll
65.     static void setup() throws Exception {
66.         ctx = E2ETestContext.create();
67.     }
68. 
69.     @AfterAll
70.     static void teardown() throws Exception {
71.         if (ctx != null) {
72.             ctx.close();
73.         }
74.     }
75. 
76.     @Test
77.     void shouldStartPingAndStopOverInProcessFfi() throws Exception {
78.         // Route the native runtime's HTTP traffic (should it make any) at the
79.         // replay proxy, mirroring how a session-level in-process test would
80.         // redirect COPILOT_API_URL. `ping` never reaches the network, but this
81.         // demonstrates the guard's intended usage for future in-process tests.
82.         // COPILOT_CLI_PATH is intentionally NOT set here: NativeRuntimeLoader and
83.         // CopilotClient.resolveInProcessEntrypoint() read it via
84.         // System.getenv(), which is a JVM-startup-time snapshot that native
85.         // setenv() calls made after the JVM starts cannot update — it must be
86.         // set before the JVM starts (see the -Pinprocess Maven profile).
87.         try (InProcessEnvGuard envGuard = new InProcessEnvGuard(Map.of("COPILOT_API_URL", ctx.getProxyUrl()))) {
88.             CopilotClientOptions options = new CopilotClientOptions().setConnection(RuntimeConnection.forInProcess());
89.             try (CopilotClient client = new CopilotClient(options)) {
90.                 client.start().get();
91. 
92.                 PingResponse pong = client.ping("ffi message").get();
93.                 assertEquals("pong: ffi message", pong.message());
94.                 assertNotNull(pong.timestamp());
95. 
96.                 client.stop().get();
97.             }
98.         }
99.     }
100. }
101.

