1. /*---------------------------------------------------------------------------------------------
2.  *  Copyright (c) Microsoft Corporation. All rights reserved.
3.  *--------------------------------------------------------------------------------------------*/
4. 
5. package com.github.copilot.ffi;
6. 
7. import java.util.ArrayList;
8. import java.util.Collections;
9. import java.util.List;
10. import java.util.Locale;
11. import java.util.Map;
12. import java.util.logging.Logger;
13. 
14. import com.sun.jna.Library;
15. import com.sun.jna.Native;
16. import com.sun.jna.WString;
17. 
18. /**
19.  * Mutates the live process environment block so that native code loaded
20.  * in-process (e.g. {@code runtime.node} via JNA) observes the given environment
21.  * variables, and restores the previous values on {@link #close()}.
22.  *
23.  * <p>
24.  * Java has no public API to modify the process-level environment block:
25.  * {@code System.setProperty()} only writes the JVM property bag, and
26.  * {@code System.getenv()} is an immutable startup-time snapshot. Native code
27.  * loaded via JNA reads the OS environment directly
28.  * ({@code GetEnvironmentVariableW} on Windows, {@code getenv()} on POSIX), so
29.  * the only way to make it see an overridden value is to call the OS API
30.  * directly through JNA.
31.  * </p>
32.  *
33.  * <p>
34.  * This mirrors the Rust {@code InProcessEnvGuard}
35.  * ({@code rust/tests/e2e/support.rs}) and the .NET
36.  * {@code InProcessEnvIsolation}
37.  * ({@code dotnet/test/Harness/InProcessEnvIsolation.cs}).
38.  * </p>
39.  *
40.  * <p>
41.  * <strong>Thread safety:</strong> this guard mutates process-global state.
42.  * Tests that use it must run with test concurrency 1 (see the
43.  * {@code -Pinprocess} Maven profile, which sets {@code failsafe.forkCount=1}
44.  * and disables parallel execution).
45.  * </p>
46.  */
47. public final class InProcessEnvGuard implements AutoCloseable {
48. 
49.     private static final Logger LOG = Logger.getLogger(InProcessEnvGuard.class.getName());
50. 
51.     /**
52.      * Environment variables suppressed because replay snapshots expect Bearer/OAuth
53.      * auth.
54.      */
55.     private static final List<String> SUPPRESSED_KEYS = List.of("COPILOT_HMAC_KEY", "CAPI_HMAC_KEY");
56. 
57.     /**
58.      * Windows kernel32: sets or deletes a variable in the process environment
59.      * block.
60.      */
61.     private interface Kernel32Env extends Library {
62.         boolean SetEnvironmentVariableW(WString lpName, WString lpValue);
63.     }
64. 
65.     /** POSIX libc: sets or deletes a variable in the process environment block. */
66.     private interface LibcEnv extends Library {
67.         int setenv(String name, String value, int overwrite);
68. 
69.         int unsetenv(String name);
70.     }
71. 
72.     /**
73.      * name -> previous value ({@code null} means the variable was not set before).
74.      */
75.     private final List<Map.Entry<String, String>> saved = new ArrayList<>();
76. 
77.     /**
78.      * Applies {@code applyEnv} to the native process environment block, saving the
79.      * previous values for restoration by {@link #close()}. Also suppresses
80.      * {@code COPILOT_HMAC_KEY} / {@code CAPI_HMAC_KEY} if present, since the replay
81.      * proxy expects Bearer/OAuth auth rather than HMAC.
82.      *
83.      * @param applyEnv
84.      *            environment variables to apply; values must not be {@code null}
85.      */
86.     public InProcessEnvGuard(Map<String, String> applyEnv) {
87.         for (Map.Entry<String, String> entry : applyEnv.entrySet()) {
88.             apply(entry.getKey(), entry.getValue());
89.         }
90.         for (String key : SUPPRESSED_KEYS) {
91.             String previous = System.getenv(key);
92.             if (previous != null && !previous.isEmpty()) {
93.                 apply(key, null);
94.             }
95.         }
96.     }
97. 
98.     private void apply(String name, String value) {
99.         String previous = System.getenv(name);
100.         saved.add(Map.entry(name, previous == null ? "" : previous));
101.         nativeSetEnv(name, value);
102.     }
103. 
104.     /**
105.      * Restores every environment variable this guard touched to the value it had
106.      * before construction.
107.      */
108.     @Override
109.     public void close() {
110.         List<Map.Entry<String, String>> reversed = new ArrayList<>(saved);
111.         Collections.reverse(reversed);
112.         for (Map.Entry<String, String> entry : reversed) {
113.             nativeSetEnv(entry.getKey(), entry.getValue().isEmpty() ? null : entry.getValue());
114.         }
115.     }
116. 
117.     private static void nativeSetEnv(String name, String value) {
118.         if (isWindows()) {
119.             nativeSetEnvWindows(name, value);
120.         } else {
121.             nativeSetEnvUnix(name, value);
122.         }
123.     }
124. 
125.     private static void nativeSetEnvWindows(String name, String value) {
126.         Kernel32Env kernel32 = Native.load("kernel32", Kernel32Env.class);
127.         boolean ok = kernel32.SetEnvironmentVariableW(new WString(name), value != null ? new WString(value) : null);
128.         if (!ok) {
129.             LOG.warning("SetEnvironmentVariableW failed for key=" + name);
130.         }
131.     }
132. 
133.     private static void nativeSetEnvUnix(String name, String value) {
134.         LibcEnv libc = Native.load("c", LibcEnv.class);
135.         if (value != null) {
136.             int rc = libc.setenv(name, value, 1);
137.             if (rc != 0) {
138.                 LOG.warning("setenv() failed for key=" + name + " rc=" + rc);
139.             }
140.         } else {
141.             int rc = libc.unsetenv(name);
