arguments.command:
REPO="github/copilot-sdk"
PR_NUMBER=2238

for COMMENT_ID in 3708516959 3708516981 3708516999 3708517014; do
  THREAD_ID=$(gh api graphql -F number=$PR_NUMBER -f query='
  query($number: Int!) {
    repository(owner: "github", name: "copilot-sdk") {
      pullRequest(number: $number) {
        reviewThreads(first: 100) {
          nodes {
            id
            isResolved
            comments(first: 1) { nodes { databaseId } }
          }
        }
      }
    }
  }' --jq ".data.repository.pullRequest.reviewThreads.nodes[] | select(.comments.nodes[0].databaseId == $COMMENT_ID) | .id")

  if [ -n "$THREAD_ID" ]; then
    gh api graphql -f query="
    mutation {
      resolveReviewThread(input: {threadId: \"$THREAD_ID\"}) {
        thread { id isResolved }
      }
    }" --jq '.data.resolveReviewThread.thread.isResolved'
    echo "Resolved thread for comment $COMMENT_ID"
  else
    echo "WARNING: Could not find thread for comment $COMMENT_ID"
  fi
done

